pub fn top_level_meta(name: &str) -> Option<&'static CommandMeta> {
    ALL_COMMAND_META
        .iter()
        .copied()
        .find(|meta| meta.container.is_none() && meta.name.eq_ignore_ascii_case(name))
}

pub fn subcommand_meta(container: &str, subcommand: &str) -> Option<&'static CommandMeta> {
    ALL_COMMAND_META.iter().copied().find(|meta| {
        let Some(meta_container) = meta.container else {
            return false;
        };
        meta_container.eq_ignore_ascii_case(container)
            && meta
                .name
                .get(meta_container.len() + 1..)
                .is_some_and(|name| name.eq_ignore_ascii_case(subcommand))
    })
}

pub fn acl_command_meta(name: &str) -> Option<&'static CommandMeta> {
    match name.split_once('|') {
        Some((container, subcommand)) => subcommand_meta(container, subcommand),
        None => top_level_meta(name),
    }
}
